11	import type { QuestionRunSubmitDetail } from "../question-run-form";
12	import "../response-panel";
13	import "../run-feedback-panel";
14	import type { ClarificationAnswers, WizardStep } from "../../workflow/workflow.types";
15	import { loadNotificationPreferences, saveNotificationPreferences } from "../../preferences";
16	import insightSpecialistAppStyles from "./styles.scss?inline";
17	
18	const TERMINAL_EVENTS = new Set(["run_succeeded", "run_failed"]);
19	const RUN_EVENT_TYPES = [
20	  "run_created",
21	  "run_started",
22	  "stage_started",
23	  "model_call_started",
24	  "model_call_succeeded",
25	  "stage_succeeded",
26	  "run_succeeded",
27	  "stage_failed",
28	  "run_failed",
29	];
30	
31	@customElement("insight-specialist-app")
32	export class InsightSpecialistApp extends LitElement {
33	  @state()
34	  private status = "idle";
35	
36	  @state()
37	  private events: RunEvent[] = [];
38	
39	  @state()
40	  private datasetProfile: DatasetProfile | null = null;
41	
42	  @state()
43	  private run: RunStartResponse | null = null;
44	
45	  @state()
46	  private snapshot: RunSnapshot | null = null;
47	
48	  @state()
49	  private error = "";
50	
51	  @state()
52	  private activeStep: WizardStep = "define";
53	
54	  @state()
55	  private submittedQuestion = "";
56	
57	  @state()
58	  private submittedFileName = "";
59	
60	  @state()
61	  private clarificationAnswers: ClarificationAnswers | null = null;
62	
63	  @state()
64	  private doNotDisturb = loadNotificationPreferences().doNotDisturb;
65	
66	  private eventSource: EventSource | null = null;
67	
68	  static styles = unsafeCSS(insightSpecialistAppStyles);
69	
70	  connectedCallback(): void {
71	    super.connectedCallback();
72	    void this.checkDesktopBackend();
73	  }
74	
75	  disconnectedCallback(): void {
76	    this.eventSource?.close();
77	    super.disconnectedCallback();
78	  }
79	
80	  render() {
81	    return html`
82	      <div class="shell">
83	        <main>
84	          <header>
85	            <div>
86	              <h1>Insight Specialist</h1>
87	              <p class="intro">
88	                Define the analysis request, answer clarification questions, and watch each step become
89	                reviewable as the backend moves forward.
90	              </p>
91	            </div>
92	            <label class="preference-toggle">
93	              <input
94	                type="checkbox"
95	                .checked=${this.doNotDisturb}
96	                @change=${this.handleDoNotDisturbChange}
97	              />
98	              <span>Do not disturb</span>
99	            </label>
100	          </header>
101	
102	          <section class="step-map">
103	            <process-map .steps=${this.processSteps} @wizard-step-select=${this.handleStepSelect}></process-map>
104	          </section>
105	
106	          <section class="panel">
107	            ${this.activeStep === "define" ? this.renderDefineStep() : null}
108	            ${this.activeStep === "clarify" ? this.renderClarifyStep() : null}
109	            ${this.activeStep === "interpret" ? this.renderInterpretStep() : null}
110	          </section>
111	
112	          ${this.error ? html`<div class="error" role="alert">${this.error}</div>` : null}
113	
114	          <section>
115	            <run-feedback-panel
116	              .status=${this.status}
117	              .events=${this.events}
118	              .datasetProfile=${this.datasetProfile}
119	            ></run-feedback-panel>
120	          </section>
121	        </main>
122	
123	        <response-panel .snapshot=${this.snapshot}></response-panel>
124	      </div>
125	    `;
126	  }
127	
128	  private renderDefineStep() {
129	    if (this.snapshot) {
130	      return html`
131	        <div class="review">
132	          <h2>Define the question</h2>
133	          <div class="review-row">
134	            <div class="review-label">Question</div>
135	            <div class="review-value">${this.submittedQuestion}</div>
136	          </div>
137	          <div class="review-row">
138	            <div class="review-label">Data file</div>
139	            <div class="review-value">${this.submittedFileName}</div>
140	          </div>
141	          <div class="review-row">
142	            <div class="review-label">Profile</div>
143	            <div class="review-value">${this.datasetProfile ? summarizeDatasetProfile(this.datasetProfile) : "No profile"}</div>
144	          </div>
145	        </div>
146	      `;
147	    }
148	
149	    return html`
150	      <question-run-form @question-run-submit=${this.handleSubmit}></question-run-form>
151	      ${this.datasetProfile
152	        ? html`<div class="profile">Temporary profile: ${summarizeDatasetProfile(this.datasetProfile)}</div>`
153	        : null}
154	    `;
155	  }
156	
157	  private renderClarifyStep() {
158	    return html`
159	      <clarification-step
160	        .spec=${this.snapshot?.result?.spec ?? null}
161	        .capturedAnswers=${this.clarificationAnswers}
162	        @clarification-answers-submit=${this.handleClarificationAnswers}
163	      ></clarification-step>
164	    `;
165	  }
166	
167	  private renderInterpretStep() {
168	    const interpretation = this.snapshot?.result?.question_interpretation;
169	    if (!interpretation) {
170	      return html`
171	        <h2>Interpret question</h2>
172	        <p class="profile">This step will use the original question, dataset profile, and clarification answers in the next slice.</p>
173	      `;
174	    }
175	    const spec = interpretation.spec;
176	    return html`
177	      <h2>Interpret question</h2>
178	      <div class="review">
179	        <div class="review-row">
180	          <div class="review-label">Intent</div>
181	          <div class="review-value">${spec.analysis_intent}</div>
182	        </div>
183	        <div class="review-row">
184	          <div class="review-label">Target</div>
185	          <div class="review-value">${spec.target_candidates.join(", ") || "No target selected"}</div>
186	        </div>
187	        <div class="review-row">
188	          <div class="review-label">Language</div>
189	          <div class="review-value">${spec.preferred_user_facing_language}</div>
190	        </div>
191	        <div class="review-row">
192	          <div class="review-label">Key columns</div>
193	          <div class="review-value">${spec.key_columns.join(", ") || "None"}</div>
194	        </div>
195	        <div class="review-row">
196	          <div class="review-label">Timing review</div>
197	          <div class="review-value">${spec.leakage_or_timing_review_columns.join(", ") || "None"}</div>
198	        </div>
199	        <div class="review-row">
200	          <div class="review-label">Reasoning</div>
201	          <div class="review-value">${spec.reasoning_summary}</div>
202	        </div>
203	      </div>
204	    `;
205	  }
206	
207	  private async handleSubmit(event: CustomEvent<QuestionRunSubmitDetail>) {
208	    this.resetRunState();
209	    this.status = "profiling";
210	    this.submittedQuestion = event.detail.question;
211	    this.submittedFileName = event.detail.dataFile.name;
212	
213	    try {
214	      const datasetProfile = buildDatasetProfileFromCsvText(event.detail.dataFile.text);
215	      this.datasetProfile = datasetProfile;
216	      this.status = "queued";
217	
218	      const run = await startQuestionClarificationRun({
219	        raw_question: event.detail.question,
220	        dataset_profile: datasetProfile,
221	      });
222	      this.run = run;
223	      this.status = run.status;
224	      await this.openEventStream(run);
225	    } catch (error) {
226	      this.status = "failed";
227	      this.error = error instanceof Error ? error.message : "Could not start the run.";
228	    }
229	  }
230	
231	  private async checkDesktopBackend() {
232	    try {
233	      await resolveApiBaseUrl();
234	    } catch (error) {
235	      this.status = "failed";
236	      this.error = error instanceof Error ? error.message : "Could not connect to the local backend.";
237	    }
238	  }
239	
240	  private async openEventStream(run: RunStartResponse) {
241	    await this.openEventStreamAfter(run, 0);
242	  }
243	
244	  private async openEventStreamAfter(run: Pick<RunStartResponse, "events_url" | "run_url">, afterEventId: number) {
245	    this.eventSource?.close();
246	    const eventsUrl = afterEventId > 0 ? `${run.events_url}?after=${afterEventId}` : run.events_url;
247	    this.eventSource = new EventSource(await toResolvedApiUrl(eventsUrl));
248	
249	    for (const type of RUN_EVENT_TYPES) {
250	      this.eventSource.addEventListener(type, (message) => {
251	        const event = JSON.parse((message as MessageEvent).data) as RunEvent;
252	        this.events = [...this.events, event];
253	        this.status = statusFromEvent(event, this.status);
254	        this.updateActiveStepFromEvent(event);
255	        if (TERMINAL_EVENTS.has(event.type)) {
256	          this.eventSource?.close();
257	          void this.loadSnapshot(run.run_url);
258	        }
259	      });
260	    }
261	
262	    this.eventSource.onerror = () => {
263	      if (this.status !== "succeeded" && this.status !== "failed") {
264	        this.error = "Lost the run event stream. The local backend may have stopped.";
265	      }
266	    };
267	  }
268	
269	  private async loadSnapshot(runUrl: string) {
270	    try {
271	      this.snapshot = await getRunSnapshot(runUrl);
272	      this.status = this.snapshot.status;
273	      if (this.snapshot.result?.question_interpretation) {
274	        this.activeStep = "interpret";
275	      } else if (this.snapshot.result?.spec.should_ask_user) {
276	        this.activeStep = "clarify";
277	      }
278	      if (this.snapshot.error) {
279	        this.error = this.snapshot.error;
280	      }
281	    } catch (error) {
282	      this.status = "failed";
283	      this.error = error instanceof Error ? error.message : "Could not load the run result.";
284	    }
285	  }
286	
287	  private resetRunState() {
288	    this.eventSource?.close();
289	    this.eventSource = null;
290	    this.events = [];
291	    this.run = null;
292	    this.snapshot = null;
293	    this.error = "";
294	    this.clarificationAnswers = null;
295	    this.activeStep = "define";
296	  }
297	
298	  private updateActiveStepFromEvent(event: RunEvent) {
299	    if (event.type !== "stage_started" && event.type !== "model_call_started") return;
300	    const step = stepFromStage(event.payload.stage);
301	    if (step) this.activeStep = step;
302	  }
303	
304	  private handleStepSelect(event: CustomEvent<{ step: WizardStep }>) {
305	    this.activeStep = event.detail.step;
306	  }
307	
308	  private async handleClarificationAnswers(event: CustomEvent<{ answers: ClarificationAnswers }>) {
309	    if (!this.run) {
310	      this.error = "No active run is available for these clarification answers.";
311	      return;
312	    }
313	    const afterEventId = this.snapshot?.event_count ?? this.events.length;
314	    this.clarificationAnswers = event.detail.answers;
315	    this.status = "running";
316	    this.error = "";
317	    try {
318	      const response = await submitClarificationAnswers(this.run.run_id, {
319	        answers: event.detail.answers,
320	      });
321	      this.snapshot = response;
322	      await this.openEventStreamAfter(response, afterEventId);
323	    } catch (error) {
324	      this.status = "failed";
325	      this.error = error instanceof Error ? error.message : "Could not submit clarification answers.";
326	    }
327	  }
328	
329	  private handleDoNotDisturbChange(event: Event) {
330	    const input = event.currentTarget as HTMLInputElement;
331	    this.doNotDisturb = input.checked;
332	    saveNotificationPreferences({ doNotDisturb: this.doNotDisturb });
333	  }
334	
335	  private get processSteps(): ProcessMapStep[] {
336	    const defineComplete = Boolean(this.run ?? this.snapshot);
337	    const clarifyAvailable = Boolean(this.run ?? this.snapshot?.result?.spec);
338	    const clarifyComplete = Boolean(this.clarificationAnswers);
339	    const interpretationAvailable = this.activeStep === "interpret" || Boolean(this.snapshot?.result?.question_interpretation);
340	    return [
341	      {
342	        id: "define",
343	        label: "Define question",
344	        status: defineComplete && this.activeStep !== "define" ? "completed" : this.activeStep === "define" ? "current" : "future",
345	        clickable: this.activeStep === "define" || defineComplete,
346	      },
347	      {
348	        id: "clarify",
349	        label: "Clarify intent",
350	        status: clarifyComplete ? "completed" : this.activeStep === "clarify" ? "current" : "future",
351	        clickable: clarifyAvailable,
352	      },
353	      {
354	        id: "interpret",
355	        label: "Interpret question",
356	        status: this.activeStep === "interpret" ? "current" : "future",
357	        clickable: interpretationAvailable,
358	      },
359	    ];
360	  }
361	}
362	
363	function stepFromStage(stage: unknown): WizardStep | null {
364	  if (stage === "question_clarification") return "clarify";
365	  if (stage === "question_interpretation") return "interpret";
366	  return null;
367	}
368	
369	function statusFromEvent(event: RunEvent, fallback: string): string {
370	  if (event.type === "run_started" || event.type === "stage_started" || event.type === "model_call_started") {
371	    return "running";
372	  }
373	  if (event.type === "run_succeeded") return "succeeded";
374	  if (event.type === "run_failed" || event.type === "stage_failed") return "failed";
375	  return fallback;
376	}
377	
378	declare global {
379	  interface HTMLElementTagNameMap {
380	    "insight-specialist-app": InsightSpecialistApp;
381	  }
382	}
383

