18	pub struct BackendSidecarState {
19	    sidecar: Mutex<Option<BackendSidecar>>,
20	}
21	
22	impl BackendSidecarState {
23	    pub fn new() -> Self {
24	        Self {
25	            sidecar: Mutex::new(None),
26	        }
27	    }
28	
29	    pub fn backend_url(&self) -> Result<String, String> {
30	        let mut sidecar = self
31	            .sidecar
32	            .lock()
33	            .map_err(|_| "Backend sidecar state is unavailable.".to_owned())?;
34	        if sidecar.is_none() {
35	            *sidecar = Some(BackendSidecar::start_or_connect());
36	        }
37	        sidecar
38	            .as_ref()
39	            .ok_or_else(|| "Backend sidecar state is unavailable.".to_owned())?
40	            .backend_url()
41	    }
42	
43	    pub fn shutdown_started_child(&self) {
44	        if let Ok(mut sidecar) = self.sidecar.lock() {
45	            if let Some(sidecar) = sidecar.as_mut() {
46	                sidecar.stop_started_child();
47	            }
48	        }
49	    }
50	}
51	
52	impl Drop for BackendSidecarState {
53	    fn drop(&mut self) {
54	        self.shutdown_started_child();
55	    }
56	}
