58	struct BackendSidecar {
59	    base_url: String,
60	    child: Option<Child>,
61	    startup_error: Option<String>,
62	}
63	
64	impl BackendSidecar {
65	    fn start_or_connect() -> Self {
66	        let configured_url = configured_backend_url();
67	        let base_url = configured_url
68	            .clone()
69	            .unwrap_or_else(|| DEFAULT_BACKEND_URL.to_owned());
70	
71	        match wait_for_backend_health(&base_url, Duration::from_millis(750)) {
72	            Ok(()) => {
73	                return Self {
74	                    base_url,
75	                    child: None,
76	                    startup_error: None,
77	                };
78	            }
79	            Err(error) if configured_url.is_some() => {
80	                return Self {
81	                    base_url: base_url.clone(),
82	                    child: None,
83	                    startup_error: Some(format!(
84	                        "Configured backend at {base_url} did not respond to GET /health: {error}"
85	                    )),
86	                };
87	            }
88	            Err(_) => {}
89	        }
90	
91	        match spawn_backend_sidecar() {
92	            Ok(mut child) => match wait_for_backend_health(&base_url, BACKEND_STARTUP_TIMEOUT) {
93	                Ok(()) => Self {
94	                    base_url,
95	                    child: Some(child),
96	                    startup_error: None,
97	                },
98	                Err(error) => {
99	                    let _ = child.kill();
100	                    let _ = child.wait();
101	                    Self {
102	                        base_url: base_url.clone(),
103	                        child: None,
104	                        startup_error: Some(format!(
105	                            "Could not start the local backend sidecar at {base_url}: {error}"
106	                        )),
107	                    }
108	                }
109	            },
110	            Err(error) => Self {
111	                base_url: base_url.clone(),
112	                child: None,
113	                startup_error: Some(format!(
114	                    "Could not start the local backend sidecar at {base_url}: {error}"
115	                )),
116	            },
117	        }
118	    }
119	
120	    fn backend_url(&self) -> Result<String, String> {
121	        if let Some(error) = &self.startup_error {
122	            return Err(error.clone());
123	        }
124	
125	        wait_for_backend_health(&self.base_url, Duration::from_millis(750))
126	            .map(|()| self.base_url.clone())
127	            .map_err(|error| {
128	                format!(
129	                    "Local backend is not available at {}. GET /health failed: {error}",
130	                    self.base_url
131	                )
132	            })
133	    }
134	
135	    fn stop_started_child(&mut self) {
136	        if let Some(mut child) = self.child.take() {
137	            let _ = child.kill();
138	            let _ = child.wait();
139	        }
140	    }
141	}
142	
143	fn configured_backend_url() -> Option<String> {
144	    env::var("INSIGHT_SPECIALIST_BACKEND_URL")
145	        .ok()
146	        .map(|value| normalize_backend_url(&value))
147	        .filter(|value| !value.is_empty())
148	}
149	
150	fn normalize_backend_url(value: &str) -> String {
151	    value.trim().trim_end_matches('/').to_owned()
152	}
153	
154	fn spawn_backend_sidecar() -> Result<Child, String> {
155	    let backend_dir = backend_dir();
156	    let python = backend_python(&backend_dir);
157	    let python_path = backend_dir.join("src");
158	
159	    Command::new(&python)
160	        .current_dir(&backend_dir)
161	        .arg("-m")
162	        .arg("uvicorn")
163	        .arg("insight_specialist_backend.main:app")
164	        .arg("--host")
165	        .arg(DEFAULT_BACKEND_HOST)
166	        .arg("--port")
167	        .arg(DEFAULT_BACKEND_PORT.to_string())
168	        .env("PYTHONPATH", python_path)
169	        .stdin(Stdio::null())
170	        .stdout(Stdio::null())
171	        .stderr(Stdio::null())
172	        .spawn()
173	        .map_err(|error| {
174	            format!(
175	                "failed to run `{}` from `{}`: {error}",
176	                python.display(),
177	                backend_dir.display()
178	            )
179	        })
180	}
181	
182	fn backend_dir() -> PathBuf {
183	    env::var("INSIGHT_SPECIALIST_BACKEND_DIR")
184	        .ok()
185	        .map(PathBuf::from)
186	        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../backend"))
187	}
188	
189	fn backend_python(backend_dir: &std::path::Path) -> PathBuf {
190	    if let Ok(value) = env::var("INSIGHT_SPECIALIST_BACKEND_PYTHON") {
191	        let trimmed = value.trim();
192	        if !trimmed.is_empty() {
193	            return PathBuf::from(trimmed);
194	        }
195	    }
196	
197	    let venv_python = if cfg!(windows) {
198	        backend_dir.join(".venv").join("Scripts").join("python.exe")
199	    } else {
200	        backend_dir.join(".venv").join("bin").join("python")
201	    };
202	
203	    if venv_python.exists() {
204	        venv_python
205	    } else {
206	        PathBuf::from("python3")
207	    }
208	}
209	
210	fn wait_for_backend_health(base_url: &str, timeout: Duration) -> Result<(), String> {
211	    wait_for_backend_health_with(
212	        base_url,
213	        timeout,
214	        BACKEND_HEALTH_POLL_INTERVAL,
215	        backend_health,
216	    )
217	}
218	
219	fn wait_for_backend_health_with<F>(
220	    base_url: &str,
221	    timeout: Duration,
222	    poll_interval: Duration,
223	    mut health: F,
224	) -> Result<(), String>
225	where
226	    F: FnMut(&str) -> Result<(), String>,
227	{
228	    let started_at = Instant::now();
229	    let mut last_error = "health check did not run".to_owned();
230	
231	    while started_at.elapsed() <= timeout {
232	        match health(base_url) {
233	            Ok(()) => return Ok(()),
234	            Err(error) => last_error = error,
235	        }
236	        thread::sleep(poll_interval);
237	    }
238	
239	    Err(last_error)
240	}
241	
242	fn backend_health(base_url: &str) -> Result<(), String> {
243	    let endpoint = parse_http_endpoint(base_url)?;
244	    let address = (endpoint.host.as_str(), endpoint.port)
245	        .to_socket_addrs()
246	        .map_err(|error| {
247	            format!(
248	                "could not resolve {}:{}: {error}",
249	                endpoint.host, endpoint.port
250	            )
251	        })?
252	        .next()
253	        .ok_or_else(|| format!("could not resolve {}:{}", endpoint.host, endpoint.port))?;
254	    let mut stream =
255	        TcpStream::connect_timeout(&address, Duration::from_millis(500)).map_err(|error| {
256	            format!(
257	                "could not connect to {}:{}: {error}",
258	                endpoint.host, endpoint.port
259	            )
260	        })?;
261	    stream
262	        .set_read_timeout(Some(Duration::from_millis(500)))
263	        .map_err(|error| format!("could not set read timeout: {error}"))?;
264	    stream
265	        .set_write_timeout(Some(Duration::from_millis(500)))
266	        .map_err(|error| format!("could not set write timeout: {error}"))?;
267	
268	    let request = format!(
269	        "GET /health HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
270	        endpoint.host
271	    );
272	    stream
273	        .write_all(request.as_bytes())
274	        .map_err(|error| format!("could not write health request: {error}"))?;
275	
276	    let mut response = String::new();
277	    stream
278	        .read_to_string(&mut response)
279	        .map_err(|error| format!("could not read health response: {error}"))?;
280	
281	    if health_response_is_ok(&response) {
282	        Ok(())
283	    } else {
284	        Err("GET /health returned a non-200 response".to_owned())
285	    }
286	}
287	
288	#[derive(Debug)]
289	struct HttpEndpoint {
290	    host: String,
291	    port: u16,
292	}
293	
294	fn parse_http_endpoint(base_url: &str) -> Result<HttpEndpoint, String> {
295	    let trimmed = normalize_backend_url(base_url);
296	    let without_scheme = trimmed.strip_prefix("http://").ok_or_else(|| {
297	        format!("only http backend URLs are supported for the local sidecar: {trimmed}")
298	    })?;
299	    let authority = without_scheme.split('/').next().unwrap_or(without_scheme);
300	    if authority.is_empty() {
301	        return Err(format!("backend URL is missing a host: {trimmed}"));
302	    }
303	
304	    let (host, port) = if let Some((host, port)) = authority.rsplit_once(':') {
305	        let parsed_port = port
306	            .parse::<u16>()
307	            .map_err(|_| format!("backend URL has an invalid port: {trimmed}"))?;
308	        (host.to_owned(), parsed_port)
309	    } else {
310	        (authority.to_owned(), 80)
311	    };
312	
313	    if host.is_empty() {
314	        return Err(format!("backend URL is missing a host: {trimmed}"));
315	    }
316	
317	    Ok(HttpEndpoint { host, port })
318	}
319	
320	fn health_response_is_ok(response: &str) -> bool {
321	    response.starts_with("HTTP/1.1 200 ") || response.starts_with("HTTP/1.0 200 ")
322	}
