339	
340	        assert_eq!(endpoint.host, "127.0.0.1");
341	        assert_eq!(endpoint.port, 8765);
342	    }
343	
344	    #[test]
345	    fn rejects_non_http_backend_endpoint() {
346	        let error = parse_http_endpoint("https://127.0.0.1:8765").expect_err("error");
347	
348	        assert!(error.contains("only http backend URLs are supported"));
349	    }
350	
351	    #[test]
352	    fn recognizes_successful_health_response() {
353	        assert!(health_response_is_ok("HTTP/1.1 200 OK\r\n\r\n{}"));
354	        assert!(!health_response_is_ok(
355	            "HTTP/1.1 503 Service Unavailable\r\n\r\n{}"
356	        ));
357	    }
358	
359	    #[test]
360	    fn initializes_without_starting_sidecar() {
361	        let state = BackendSidecarState::new();
362	
363	        assert!(state.sidecar.lock().expect("state lock").is_none());
364	    }
365	
366	    #[test]
367	    fn waits_for_successful_backend_health_response() {
368	        let mut calls = 0;
369	
370	        wait_for_backend_health_with(
371	            "http://127.0.0.1:8765",
372	            Duration::from_millis(1),
373	            Duration::ZERO,
374	            |url| {
375	                calls += 1;
376	                assert_eq!(url, "http://127.0.0.1:8765");
377	                Ok(())
378	            },
379	        )
380	        .expect("health");
381	
382	        assert_eq!(calls, 1);
383	    }
