use std::{
    env,
    io::{Read, Write},
    net::{TcpStream, ToSocketAddrs},
    path::PathBuf,
    process::{Child, Command, Stdio},
    sync::Mutex,
    thread,
    time::{Duration, Instant},
};

const DEFAULT_BACKEND_HOST: &str = "127.0.0.1";
const DEFAULT_BACKEND_PORT: u16 = 8765;
const DEFAULT_BACKEND_URL: &str = "http://127.0.0.1:8765";
const BACKEND_STARTUP_TIMEOUT: Duration = Duration::from_secs(12);
const BACKEND_HEALTH_POLL_INTERVAL: Duration = Duration::from_millis(250);

pub struct BackendSidecarState {
    sidecar: Mutex<Option<BackendSidecar>>,
}

impl BackendSidecarState {
    pub fn new() -> Self {
        Self {
            sidecar: Mutex::new(None),
        }
    }

    pub fn backend_url(&self) -> Result<String, String> {
        let mut sidecar = self
            .sidecar
            .lock()
            .map_err(|_| "Backend sidecar state is unavailable.".to_owned())?;
        if sidecar.is_none() {
            *sidecar = Some(BackendSidecar::start_or_connect());
        }
        sidecar
            .as_ref()
            .ok_or_else(|| "Backend sidecar state is unavailable.".to_owned())?
            .backend_url()
    }

    pub fn shutdown_started_child(&self) {
        if let Ok(mut sidecar) = self.sidecar.lock() {
            if let Some(sidecar) = sidecar.as_mut() {
                sidecar.stop_started_child();
            }
        }
    }
}

impl Drop for BackendSidecarState {
    fn drop(&mut self) {
        self.shutdown_started_child();
    }
}

struct BackendSidecar {
    base_url: String,
    child: Option<Child>,
    startup_error: Option<String>,
}

impl BackendSidecar {
    fn start_or_connect() -> Self {
        let configured_url = configured_backend_url();
        let base_url = configured_url
            .clone()
            .unwrap_or_else(|| DEFAULT_BACKEND_URL.to_owned());

        match wait_for_backend_health(&base_url, Duration::from_millis(750)) {
            Ok(()) => {
                return Self {
                    base_url,
                    child: None,
                    startup_error: None,
                };
            }
            Err(error) if configured_url.is_some() => {
                return Self {
                    base_url: base_url.clone(),
                    child: None,
                    startup_error: Some(format!(
                        "Configured backend at {base_url} did not respond to GET /health: {error}"
                    )),
                };
            }
            Err(_) => {}
        }

        match spawn_backend_sidecar() {
            Ok(mut child) => match wait_for_backend_health(&base_url, BACKEND_STARTUP_TIMEOUT) {
                Ok(()) => Self {
                    base_url,
                    child: Some(child),
                    startup_error: None,
                },
                Err(error) => {
                    let _ = child.kill();
                    let _ = child.wait();
                    Self {
                        base_url: base_url.clone(),
                        child: None,
                        startup_error: Some(format!(
                            "Could not start the local backend sidecar at {base_url}: {error}"
                        )),
                    }
                }
            },
            Err(error) => Self {
                base_url: base_url.clone(),
                child: None,
                startup_error: Some(format!(
                    "Could not start the local backend sidecar at {base_url}: {error}"
                )),
            },
        }
    }

    fn backend_url(&self) -> Result<String, String> {
        if let Some(error) = &self.startup_error {
            return Err(error.clone());
        }

        wait_for_backend_health(&self.base_url, Duration::from_millis(750))
            .map(|()| self.base_url.clone())
            .map_err(|error| {
                format!(
                    "Local backend is not available at {}. GET /health failed: {error}",
                    self.base_url
                )
            })
    }

    fn stop_started_child(&mut self) {
        if let Some(mut child) = self.child.take() {
            let _ = child.kill();
            let _ = child.wait();
        }
    }
}

fn configured_backend_url() -> Option<String> {
    env::var("INSIGHT_SPECIALIST_BACKEND_URL")
        .ok()
        .map(|value| normalize_backend_url(&value))
        .filter(|value| !value.is_empty())
}

fn normalize_backend_url(value: &str) -> String {
    value.trim().trim_end_matches('/').to_owned()
}

fn spawn_backend_sidecar() -> Result<Child, String> {
    let backend_dir = backend_dir();
    let python = backend_python(&backend_dir);
    let python_path = backend_dir.join("src");

    Command::new(&python)
        .current_dir(&backend_dir)
        .arg("-m")
        .arg("uvicorn")
        .arg("insight_specialist_backend.main:app")
        .arg("--host")
        .arg(DEFAULT_BACKEND_HOST)
        .arg("--port")
        .arg(DEFAULT_BACKEND_PORT.to_string())
        .env("PYTHONPATH", python_path)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|error| {
            format!(
                "failed to run `{}` from `{}`: {error}",
                python.display(),
                backend_dir.display()
            )
        })
}

fn backend_dir() -> PathBuf {
    env::var("INSIGHT_SPECIALIST_BACKEND_DIR")
        .ok()
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../backend"))
}

fn backend_python(backend_dir: &std::path::Path) -> PathBuf {
    if let Ok(value) = env::var("INSIGHT_SPECIALIST_BACKEND_PYTHON") {
        let trimmed = value.trim();
        if !trimmed.is_empty() {
            return PathBuf::from(trimmed);
        }
    }

    let venv_python = if cfg!(windows) {
        backend_dir.join(".venv").join("Scripts").join("python.exe")
    } else {
        backend_dir.join(".venv").join("bin").join("python")
    };

    if venv_python.exists() {
        venv_python
    } else {
        PathBuf::from("python3")
    }
}

fn wait_for_backend_health(base_url: &str, timeout: Duration) -> Result<(), String> {
    wait_for_backend_health_with(
        base_url,
        timeout,
        BACKEND_HEALTH_POLL_INTERVAL,
        backend_health,
    )
}

fn wait_for_backend_health_with<F>(
    base_url: &str,
    timeout: Duration,
    poll_interval: Duration,
    mut health: F,
) -> Result<(), String>
where
    F: FnMut(&str) -> Result<(), String>,
{
    let started_at = Instant::now();
    let mut last_error = "health check did not run".to_owned();

    while started_at.elapsed() <= timeout {
        match health(base_url) {
            Ok(()) => return Ok(()),
            Err(error) => last_error = error,
        }
        thread::sleep(poll_interval);
    }

    Err(last_error)
}

fn backend_health(base_url: &str) -> Result<(), String> {
    let endpoint = parse_http_endpoint(base_url)?;
    let address = (endpoint.host.as_str(), endpoint.port)
        .to_socket_addrs()
        .map_err(|error| {
            format!(
                "could not resolve {}:{}: {error}",
                endpoint.host, endpoint.port
            )
        })?
        .next()
        .ok_or_else(|| format!("could not resolve {}:{}", endpoint.host, endpoint.port))?;
    let mut stream =
        TcpStream::connect_timeout(&address, Duration::from_millis(500)).map_err(|error| {
            format!(
                "could not connect to {}:{}: {error}",
                endpoint.host, endpoint.port
            )
        })?;
    stream
        .set_read_timeout(Some(Duration::from_millis(500)))
        .map_err(|error| format!("could not set read timeout: {error}"))?;
    stream
        .set_write_timeout(Some(Duration::from_millis(500)))
        .map_err(|error| format!("could not set write timeout: {error}"))?;

    let request = format!(
        "GET /health HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
        endpoint.host
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|error| format!("could not write health request: {error}"))?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|error| format!("could not read health response: {error}"))?;

    if health_response_is_ok(&response) {
        Ok(())
    } else {
        Err("GET /health returned a non-200 response".to_owned())
    }
}

#[derive(Debug)]
struct HttpEndpoint {
    host: String,
    port: u16,
}

fn parse_http_endpoint(base_url: &str) -> Result<HttpEndpoint, String> {
    let trimmed = normalize_backend_url(base_url);
    let without_scheme = trimmed.strip_prefix("http://").ok_or_else(|| {
        format!("only http backend URLs are supported for the local sidecar: {trimmed}")
    })?;
    let authority = without_scheme.split('/').next().unwrap_or(without_scheme);
    if authority.is_empty() {
        return Err(format!("backend URL is missing a host: {trimmed}"));
    }

    let (host, port) = if let Some((host, port)) = authority.rsplit_once(':') {
        let parsed_port = port
            .parse::<u16>()
            .map_err(|_| format!("backend URL has an invalid port: {trimmed}"))?;
        (host.to_owned(), parsed_port)
    } else {
        (authority.to_owned(), 80)
    };

    if host.is_empty() {
        return Err(format!("backend URL is missing a host: {trimmed}"));
    }

    Ok(HttpEndpoint { host, port })
}

fn health_response_is_ok(response: &str) -> bool {
    response.starts_with("HTTP/1.1 200 ") || response.starts_with("HTTP/1.0 200 ")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn normalizes_backend_urls() {
        assert_eq!(
            normalize_backend_url(" http://127.0.0.1:8765/// "),
            "http://127.0.0.1:8765"
        );
    }

    #[test]
    fn parses_http_backend_endpoint() {
        let endpoint = parse_http_endpoint("http://127.0.0.1:8765/health").expect("endpoint");

        assert_eq!(endpoint.host, "127.0.0.1");
        assert_eq!(endpoint.port, 8765);
    }

    #[test]
    fn rejects_non_http_backend_endpoint() {
        let error = parse_http_endpoint("https://127.0.0.1:8765").expect_err("error");

        assert!(error.contains("only http backend URLs are supported"));
    }

    #[test]
    fn recognizes_successful_health_response() {
        assert!(health_response_is_ok("HTTP/1.1 200 OK\r\n\r\n{}"));
        assert!(!health_response_is_ok(
            "HTTP/1.1 503 Service Unavailable\r\n\r\n{}"
        ));
    }

    #[test]
    fn initializes_without_starting_sidecar() {
        let state = BackendSidecarState::new();

        assert!(state.sidecar.lock().expect("state lock").is_none());
    }

    #[test]
    fn waits_for_successful_backend_health_response() {
        let mut calls = 0;

        wait_for_backend_health_with(
            "http://127.0.0.1:8765",
            Duration::from_millis(1),
            Duration::ZERO,
            |url| {
                calls += 1;
                assert_eq!(url, "http://127.0.0.1:8765");
                Ok(())
            },
        )
        .expect("health");

        assert_eq!(calls, 1);
    }
}

