mod backend_sidecar;

use backend_sidecar::BackendSidecarState;
use serde::Serialize;
use std::{env, fs, path::PathBuf};
use tauri::Manager;

const MAX_SELECTED_CSV_BYTES: u64 = 10 * 1024 * 1024;
const AUTOMATED_PICK_CSV_PATH_ENV: &str = "INSIGHT_SPECIALIST_DESKTOP_AUTOMATED_PICK_CSV_PATH";
const OPEN_DEVTOOLS_ENV: &str = "INSIGHT_SPECIALIST_DESKTOP_OPEN_DEVTOOLS";

#[derive(Debug, Serialize)]
struct SelectedCsvFile {
    name: String,
    path: String,
    size: Option<u64>,
    text: String,
}

#[tauri::command]
fn get_backend_url(state: tauri::State<'_, BackendSidecarState>) -> Result<String, String> {
    state.backend_url()
}

#[tauri::command]
async fn pick_csv_file() -> Result<Option<SelectedCsvFile>, String> {
    if let Some(selected) = automated_selected_csv_file(env::var(AUTOMATED_PICK_CSV_PATH_ENV).ok())?
    {
        return Ok(Some(selected));
    }

    let Some(file) = rfd::AsyncFileDialog::new()
        .set_title("Choose CSV data")
        .add_filter("CSV or text", &["csv", "txt"])
        .pick_file()
        .await
    else {
        return Ok(None);
    };

    read_selected_csv_file(file.path().to_path_buf()).map(Some)
}

fn automated_selected_csv_file(value: Option<String>) -> Result<Option<SelectedCsvFile>, String> {
    let Some(value) = value else {
        return Ok(None);
    };
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }

    read_selected_csv_file(PathBuf::from(trimmed)).map(Some)
}

fn read_selected_csv_file(path: PathBuf) -> Result<SelectedCsvFile, String> {
    if !is_csv_like_path(&path) {
        return Err("Choose a CSV or plain-text CSV file.".to_string());
    }

    let metadata =
        fs::metadata(&path).map_err(|error| format!("Could not inspect selected file: {error}"))?;
    if !metadata.is_file() {
        return Err("Choose a CSV file, not a folder.".to_string());
    }
    if metadata.len() > MAX_SELECTED_CSV_BYTES {
        return Err(
            "Choose a CSV file smaller than 10 MB for this temporary desktop flow.".to_string(),
        );
    }

    let text = fs::read_to_string(&path)
        .map_err(|error| format!("Could not read selected file: {error}"))?;
    let name = path
        .file_name()
        .and_then(|value| value.to_str())
        .ok_or_else(|| "Selected file did not have a readable file name.".to_string())?
        .to_string();

    Ok(SelectedCsvFile {
        name,
        path: path.display().to_string(),
        size: Some(metadata.len()),
        text,
    })
}

fn is_csv_like_path(path: &PathBuf) -> bool {
    matches!(
        path.extension()
            .and_then(|value| value.to_str())
            .map(|value| value.to_ascii_lowercase()),
        Some(extension) if extension == "csv" || extension == "txt"
    )
}

fn main() {
    let app = tauri::Builder::default()
        .setup(|app| {
            app.manage(BackendSidecarState::new());

            #[cfg(debug_assertions)]
            if env_value_enabled(env::var(OPEN_DEVTOOLS_ENV).ok()) {
                if let Some(window) = app.get_webview_window("main") {
                    window.open_devtools();
                } else {
                    println!("Could not open devtools: no Tauri window labeled 'main'.");
                }
            }

            Ok(())
        })
        .invoke_handler(tauri::generate_handler![get_backend_url, pick_csv_file])
        .build(tauri::generate_context!())
        .expect("error while building Tauri application");

    app.run(|app_handle, event| match event {
        tauri::RunEvent::WindowEvent {
            event: tauri::WindowEvent::CloseRequested { .. },
            ..
        }
        | tauri::RunEvent::ExitRequested { .. }
        | tauri::RunEvent::Exit => {
            shutdown_backend_sidecar(app_handle);
        }
        _ => {}
    });
}

fn env_value_enabled(value: Option<String>) -> bool {
    matches!(
        value.as_deref().map(str::trim).map(str::to_ascii_lowercase),
        Some(value) if value == "1" || value == "true" || value == "yes" || value == "on"
    )
}

fn shutdown_backend_sidecar(app_handle: &tauri::AppHandle) {
    if let Some(state) = app_handle.try_state::<BackendSidecarState>() {
        state.shutdown_started_child();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{env, fs, process};

    #[test]
    fn reads_csv_like_file_metadata_and_text() {
        let path = write_temp_file("customer-churn.csv", "id,canceled\n1,true\n");

        let selected = read_selected_csv_file(path.clone()).expect("file should read");

        assert_eq!(selected.name, "customer-churn.csv");
        assert_eq!(selected.size, Some(19));
        assert_eq!(selected.text, "id,canceled\n1,true\n");
        assert_eq!(selected.path, path.display().to_string());
        let _ = fs::remove_file(path);
    }

    #[test]
    fn rejects_unsupported_file_extension() {
        let path = write_temp_file("customer-churn.json", "{\"rows\":[]}");

        let error = read_selected_csv_file(path.clone()).expect_err("json should be rejected");

        assert!(error.contains("CSV or plain-text CSV"));
        let _ = fs::remove_file(path);
    }

    #[test]
    fn reads_automated_csv_file_selection_from_env_value() {
        let path = write_temp_file("automated-churn.csv", "id,canceled\n1,true\n");

        let selected = automated_selected_csv_file(Some(path.display().to_string()))
            .expect("automated file should read")
            .expect("automated file should be selected");

        assert_eq!(selected.name, "automated-churn.csv");
        assert_eq!(selected.text, "id,canceled\n1,true\n");
        let _ = fs::remove_file(path);
    }

    #[test]
    fn ignores_blank_automated_csv_file_selection() {
        let selected = automated_selected_csv_file(Some("   ".to_string()))
            .expect("blank automated value should be ignored");

        assert!(selected.is_none());
    }

    #[test]
    fn parses_enabled_env_values() {
        assert!(env_value_enabled(Some("1".to_string())));
        assert!(env_value_enabled(Some(" true ".to_string())));
        assert!(env_value_enabled(Some("YES".to_string())));
        assert!(env_value_enabled(Some("on".to_string())));
    }

    #[test]
    fn rejects_disabled_env_values() {
        assert!(!env_value_enabled(None));
        assert!(!env_value_enabled(Some("".to_string())));
        assert!(!env_value_enabled(Some("0".to_string())));
        assert!(!env_value_enabled(Some("false".to_string())));
    }

    fn write_temp_file(name: &str, contents: &str) -> PathBuf {
        let directory = env::temp_dir().join(format!("insight-specialist-desktop-{}", process::id()));
        fs::create_dir_all(&directory).expect("temp directory should be created");
        let path = directory.join(name);
        fs::write(&path, contents).expect("temp file should write");
        path
    }
}
