export type WizardStep = "define" | "clarify" | "interpret";

export type WizardStepStatus = "completed" | "current" | "future";

export type ClarificationAnswers = Record<string, string>;
export interface NotificationPreferences {
  doNotDisturb: boolean;
}

const NOTIFICATION_PREFERENCES_KEY = "insight-specialist.notification-preferences.v1";

export const DEFAULT_NOTIFICATION_PREFERENCES: NotificationPreferences = {
  doNotDisturb: false,
};

export function loadNotificationPreferences(storage: Storage = window.localStorage): NotificationPreferences {
  try {
    const rawValue = storage.getItem(NOTIFICATION_PREFERENCES_KEY);
    if (!rawValue) return DEFAULT_NOTIFICATION_PREFERENCES;

    const parsedValue = JSON.parse(rawValue) as Partial<NotificationPreferences>;
    return {
      doNotDisturb:
        typeof parsedValue.doNotDisturb === "boolean"
          ? parsedValue.doNotDisturb
          : DEFAULT_NOTIFICATION_PREFERENCES.doNotDisturb,
    };
  } catch {
    return DEFAULT_NOTIFICATION_PREFERENCES;
  }
}

export function saveNotificationPreferences(
  preferences: NotificationPreferences,
  storage: Storage = window.localStorage,
): void {
  storage.setItem(NOTIFICATION_PREFERENCES_KEY, JSON.stringify(preferences));
}

