        Some(value) if value == "1" || value == "true" || value == "yes" || value == "on"
    )
}

fn shutdown_backend_sidecar(app_handle: &tauri::AppHandle) {
    if let Some(state) = app_handle.try_state::<BackendSidecarState>() {
        state.shutdown_started_child();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{env, fs, process};

    #[test]
    fn reads_csv_like_file_metadata_and_text() {
        let path = write_temp_file("customer-churn.csv", "id,canceled\n1,true\n");

        let selected = read_selected_csv_file(path.clone()).expect("file should read");

        assert_eq!(selected.name, "customer-churn.csv");
        assert_eq!(selected.size, Some(19));
        assert_eq!(selected.text, "id,canceled\n1,true\n");
        assert_eq!(selected.path, path.display().to_string());
        let _ = fs::remove_file(path);
    }

    #[test]
    fn rejects_unsupported_file_extension() {
        let path = write_temp_file("customer-churn.json", "{\"rows\":[]}");

        let error = read_selected_csv_file(path.clone()).expect_err("json should be rejected");

        assert!(error.contains("CSV or plain-text CSV"));
        let _ = fs::remove_file(path);
    }

    #[test]
    fn reads_automated_csv_file_selection_from_env_value() {
        let path = write_temp_file("automated-churn.csv", "id,canceled\n1,true\n");

        let selected = automated_selected_csv_file(Some(path.display().to_string()))
            .expect("automated file should read")
            .expect("automated file should be selected");

        assert_eq!(selected.name, "automated-churn.csv");
        assert_eq!(selected.text, "id,canceled\n1,true\n");
        let _ = fs::remove_file(path);
    }

    #[test]
    fn ignores_blank_automated_csv_file_selection() {
        let selected = automated_selected_csv_file(Some("   ".to_string()))
            .expect("blank automated value should be ignored");

        assert!(selected.is_none());
    }

    #[test]
    fn parses_enabled_env_values() {
        assert!(env_value_enabled(Some("1".to_string())));
        assert!(env_value_enabled(Some(" true ".to_string())));
        assert!(env_value_enabled(Some("YES".to_string())));
        assert!(env_value_enabled(Some("on".to_string())));
    }

    #[test]
    fn rejects_disabled_env_values() {
        assert!(!env_value_enabled(None));
        assert!(!env_value_enabled(Some("".to_string())));
        assert!(!env_value_enabled(Some("0".to_string())));
        assert!(!env_value_enabled(Some("false".to_string())));
    }

    fn write_temp_file(name: &str, contents: &str) -> PathBuf {
        let directory = env::temp_dir().join(format!("insight-specialist-desktop-{}", process::id()));
        fs::create_dir_all(&directory).expect("temp directory should be created");
        let path = directory.join(name);
        fs::write(&path, contents).expect("temp file should write");
        path
    }
}
